(() => {
  const styleImports = (map.getStyle() && map.getStyle().imports) || [];
  const importId = map.getSchema('basemap') ? 'basemap' : ((styleImports[0] && styleImports[0].id) || 'basemap');
  const schema = map.getSchema(importId) || {};

  const laneRe = /\blanes?\b|lane[-\s]?level/i;
  const strongRe = /lane[-\s]?level|individual\s+lanes?|road\s+lanes?|lane\s+(markings?|detail|geometry)/i;
  const weakRe = /\b(bike|bicycle|cycle|cycling|bus)\s+lanes?\b/i;

  const candidates = [];
  for (const [name, opt] of Object.entries(schema)) {
    const meta = (opt && opt.metadata) || {};
    const title = String(meta['mapbox:title'] || '');
    const desc = String(meta['mapbox:description'] || '');
    const text = `${name} ${title} ${desc}`;
    const nameSplit = name.replace(/([a-z0-9])([A-Z])/g, '$1 $2');
    if (!laneRe.test(text) && !laneRe.test(nameSplit)) continue;

    const values = Array.isArray(opt.values) ? opt.values : null;
    const isBool = opt.type === 'boolean' || typeof opt.default === 'boolean';
    let value;
    if (isBool) {
      value = true;
    } else if (values) {
      value = values.find(v => laneRe.test(String(v)));
      if (value === undefined) continue;
    } else {
      continue;
    }

    let score = 0;
    if (laneRe.test(nameSplit)) score += 3;
    if (laneRe.test(title)) score += 2;
    if (laneRe.test(desc)) score += 1;
    if (strongRe.test(text) || strongRe.test(nameSplit)) score += 4;
    if (weakRe.test(text) || weakRe.test(nameSplit)) score -= 5;
    candidates.push({ name, title, value, score });
  }

  candidates.sort((a, b) => b.score - a.score);
  const best = candidates.filter(c => c.score > 0 && c.score === (candidates[0] && candidates[0].score));

  if (!best.length) {
    console.warn(`No lane-level setting found in the "${importId}" schema. Available options:`, Object.keys(schema));
    return;
  }

  for (const c of best) {
    map.setConfigProperty(importId, c.name, c.value);
    const actual = map.getConfigProperty(importId, c.name);
    if (actual === c.value) {
      console.log(`Lane detail enabled: ${importId}.${c.name} = ${JSON.stringify(actual)}${c.title ? ` ("${c.title}")` : ''}`);
    } else {
      console.warn(`Setting ${importId}.${c.name} did not take effect (read back ${JSON.stringify(actual)}).`);
    }
  }
})();

