const TARGET_COLOUR = '#555555';
const schema = map.getSchema('basemap') || {};

const textOf = (name, entry) => {
  const md = (entry && entry.metadata) || {};
  return [name, md['mapbox:title'] || '', md['mapbox:description'] || ''].join(' ').replace(/([a-z])([A-Z])/g, '$1 $2').toLowerCase();
};

const isColour = (entry) => {
  const t = entry && entry.type;
  const d = entry && entry.default;
  return t === 'color' || (typeof d === 'string' && /^(#|rgb|hsl)/i.test(d)) || (Array.isArray(d) && d[0] === 'rgba');
};

const candidates = Object.keys(schema)
  .map((name) => {
    const entry = schema[name];
    const text = textOf(name, entry);
    let score = 0;
    if (/\blane[s]?\b|lane-level|lanelevel/.test(text)) score += 5;
    if (/\bsurface[s]?\b/.test(text)) score += 3;
    if (/\broad[s]?\b|\bstreet[s]?\b/.test(text)) score += 1;
    if (/\bmarking[s]?\b|\bstripe[s]?\b|\blabel[s]?\b|\barrow[s]?\b|\bshield[s]?\b/.test(text)) score -= 4;
    if (!isColour(entry)) score -= 10;
    return { name, score, text };
  })
  .filter((c) => c.score >= 5)
  .sort((a, b) => b.score - a.score);

const toHex = (v) => {
  if (v == null) return null;
  if (typeof v === 'object' && 'r' in v && 'g' in v && 'b' in v) {
    const scale = v.r <= 1 && v.g <= 1 && v.b <= 1 ? 255 : 1;
    const a = v.a == null ? 1 : v.a;
    const ch = (x) => Math.round((a && scale === 255 ? x / a : x) * scale).toString(16).padStart(2, '0');
    return ('#' + ch(v.r) + ch(v.g) + ch(v.b)).toLowerCase();
  }
  const s = String(v).trim().toLowerCase();
  const m = s.match(/^rgba?\(\s*(\d+)\s*,\s*(\d+)\s*,\s*(\d+)/);
  if (m) return '#' + [m[1], m[2], m[3]].map((n) => Number(n).toString(16).padStart(2, '0')).join('');
  if (/^#[0-9a-f]{3}$/.test(s)) return '#' + s.slice(1).split('').map((c) => c + c).join('');
  return s;
};

if (candidates.length === 0) {
  const colourSettings = Object.keys(schema).filter((n) => isColour(schema[n])).map((n) => n + ' — ' + textOf(n, schema[n]));
  console.warn('No lane-level road surface colour setting found in the basemap schema. Available colour settings:', colourSettings);
} else {
  const key = candidates[0].name;
  map.setConfigProperty('basemap', key, TARGET_COLOUR);
  const applied = map.getConfigProperty('basemap', key);
  if (toHex(applied) === TARGET_COLOUR.toLowerCase()) {
    console.log('Lane-level road surface colour set via "' + key + '":', applied);
  } else {
    console.warn('Setting "' + key + '" did not read back as ' + TARGET_COLOUR + '; got:', applied, 'Other candidates:', candidates.slice(1).map((c) => c.name));
  }
}

