(function () {
  const IMPORT_ID = 'basemap';

  function run() {
    let schema = null;
    try { schema = map.getSchema(IMPORT_ID); } catch (e) {}
    if (!schema || typeof schema !== 'object') {
      console.warn('[lanes] No config schema found for import "' + IMPORT_ID + '".');
      return;
    }

    const norm = (s) => String(s == null ? '' : s)
      .replace(/([a-z0-9])([A-Z])/g, '$1 $2')
      .replace(/[_\-.]+/g, ' ')
      .toLowerCase();
    const laneRe = /\blanes?\b|\blane level\b/;
    const negRe = /\b(hide|hides|disable|disables|remove|removes|suppress)\b/;

    const applied = [];

    Object.entries(schema).forEach(([name, opt]) => {
      opt = opt || {};
      const meta = opt.metadata || {};
      const title = meta['mapbox:title'];
      const desc = meta['mapbox:description'];
      const nameText = norm(name);
      const titleText = norm(title);
      const descText = norm(desc);
      const allText = [nameText, titleText, descText].join(' | ');
      if (!laneRe.test(allText)) return;

      let target;
      const isBool = opt.type === 'boolean' || typeof opt.default === 'boolean';
      if (isBool) {
        target = !negRe.test(nameText + ' ' + titleText);
      } else if (Array.isArray(opt.values) && opt.values.length) {
        const vals = opt.values;
        target =
          vals.find((v) => laneRe.test(norm(v))) ??
          vals.find((v) => /\b(detailed|detail|full|all|high|max)\b/.test(norm(v)));
        if (target === undefined) return;
      } else {
        return;
      }

      try {
        map.setConfigProperty(IMPORT_ID, name, target);
      } catch (e) {
        console.warn('[lanes] Failed to set "' + name + '":', e);
        return;
      }

      let readBack;
      try { readBack = map.getConfigProperty(IMPORT_ID, name); } catch (e) {}
      const ok = JSON.stringify(readBack) === JSON.stringify(target);
      applied.push({ name, title, target, readBack, ok });
    });

    if (!applied.length) {
      console.warn('[lanes] No lane-related setting found in the "' + IMPORT_ID + '" schema. Available settings:',
        Object.entries(schema).map(([n, o]) => ({
          name: n,
          title: o && o.metadata && o.metadata['mapbox:title'],
          description: o && o.metadata && o.metadata['mapbox:description']
        })));
      return;
    }

    applied.forEach((r) => {
      if (r.ok) {
        console.log('[lanes] "' + r.name + '"' + (r.title ? ' (' + r.title + ')' : '') + ' set to', r.readBack);
      } else {
        console.warn('[lanes] "' + r.name + '" did not take effect: wanted', r.target, 'but read back', r.readBack);
      }
    });
  }

  if (map.isStyleLoaded()) run(); else map.once('style.load', run);
})();

