(() => {
  const IMPORT_ID = 'basemap';
  const TARGET = '#555555';

  const hex2 = n => Math.max(0, Math.min(255, Math.round(+n))).toString(16).padStart(2, '0');
  const normalise = v => {
    if (v == null) return null;
    if (typeof v === 'string') {
      const s = v.trim().toLowerCase();
      if (/^#[0-9a-f]{3}$/.test(s)) return '#' + s.slice(1).split('').map(c => c + c).join('');
      if (/^#[0-9a-f]{6}$/.test(s)) return s;
      const m = s.match(/^rgba?\(\s*([\d.]+)\s*,\s*([\d.]+)\s*,\s*([\d.]+)/);
      return m ? '#' + m.slice(1, 4).map(hex2).join('') : s;
    }
    if (Array.isArray(v)) {
      if ((v[0] === 'rgba' || v[0] === 'rgb') && v.length >= 4) return '#' + v.slice(1, 4).map(hex2).join('');
      if (v[0] === 'literal' || v[0] === 'to-color') return normalise(v[1]);
      return JSON.stringify(v);
    }
    if (typeof v === 'object' && 'r' in v && 'g' in v && 'b' in v) {
      return '#' + [v.r, v.g, v.b].map(c => hex2(c * 255)).join('');
    }
    return String(v);
  };

  const mentionsLane = s => /(^|[^a-zA-Z])lanes?/i.test(s) || /[a-z]Lanes?/.test(s);
  const looksLikeColour = def =>
    def.type === 'color' ||
    (typeof def.default === 'string' && /^(#|rgb|hsl)/i.test(def.default.trim()));

  const run = () => {
    let schema = {};
    try {
      schema = (typeof map.getSchema === 'function' && map.getSchema(IMPORT_ID)) || {};
    } catch (e) {
      console.warn('Could not read basemap schema:', e);
    }

    const entries = Object.entries(schema).map(([name, def]) => {
      def = def || {};
      const md = def.metadata || {};
      const title = String(md['mapbox:title'] || '');
      const desc = String(md['mapbox:description'] || '');
      return { name, def, title, desc };
    });

    const score = e => {
      const nameTitle = `${e.name} ${e.title}`;
      const all = `${e.name} ${e.title} ${e.desc}`;
      if (!mentionsLane(all)) return -Infinity;
      if (!(looksLikeColour(e.def) || /colou?r/i.test(nameTitle))) return -Infinity;
      let s = 0;
      if (mentionsLane(e.name)) s += 4;
      if (mentionsLane(e.title)) s += 3;
      if (/lane[\s_-]*level/i.test(all)) s += 3;
      if (/surface|pavement|road|fill|area/i.test(nameTitle)) s += 2;
      if (/surface/i.test(all)) s += 2;
      if (/colou?r/i.test(nameTitle)) s += 1;
      if (/marking|label|arrow|stripe|text|icon|line|border|casing|outline|divider/i.test(nameTitle)) s -= 6;
      return s;
    };

    const ranked = entries
      .map(e => ({ ...e, score: score(e) }))
      .filter(e => e.score > 0)
      .sort((a, b) => b.score - a.score);

    let key = ranked.length ? ranked[0].name : null;

    if (!key) {
      const guesses = ['colorLaneLevelRoads', 'colorRoadsLaneLevel', 'colorLaneLevelRoad', 'colorLaneRoads', 'colorRoadLanes', 'colorLanes'];
      key = guesses.find(g => {
        try {
          return map.getConfigProperty(IMPORT_ID, g) != null;
        } catch (e) {
          return false;
        }
      }) || null;
    }

    if (!key) {
      console.warn(
        'No lane-level road surface colour setting found in the basemap config. Colour settings available:',
        entries
          .filter(e => looksLikeColour(e.def) || /colou?r/i.test(`${e.name} ${e.title}`))
          .map(e => ({ name: e.name, title: e.title, description: e.desc }))
      );
      return;
    }

    if (ranked.length > 1) {
      console.info('Lane-level colour candidates (best first):', ranked.map(e => ({ name: e.name, title: e.title, score: e.score })));
    }

    const before = map.getConfigProperty(IMPORT_ID, key);
    map.setConfigProperty(IMPORT_ID, key, TARGET);
    const after = map.getConfigProperty(IMPORT_ID, key);

    if (normalise(after) === TARGET) {
      console.info(`Set basemap config "${key}" to ${TARGET} (was ${JSON.stringify(before)}).`);
    } else {
      console.warn(`Tried to set basemap config "${key}" to ${TARGET}, but it reads back as ${JSON.stringify(after)}.`);
    }
  };

  if (map.isStyleLoaded()) {
    run();
  } else {
    map.once('style.load', run);
  }
})();

