    return [splitWords(name), md['mapbox:title'], md['mapbox:description']].filter(Boolean).join(' | ');
  };
  const LANE_RE = /\blanes?\b|lane[-\s]?level/i;
  const OTHER_LANE_RE = /\b(bike|bicycle|cycle|cycling|bus|transit)\s+lanes?\b/i;

  const isBooleanOption = (opt) =>
    opt && (opt.type === 'boolean' || typeof opt.default === 'boolean');

  const pickEnumValue = (opt) => {
    const values = Array.isArray(opt && opt.values) ? opt.values : null;
    if (!values || !values.length) return undefined;
    return (
      values.find((v) => /lane/i.test(String(v))) ??
      values.find((v) => /^(all|full|detailed|detail|high|on|true|enabled?)$/i.test(String(v)))
    );
  };

  const candidates = Object.keys(schema)
    .map((name) => ({ name, opt: schema[name], text: describe(name, schema[name]) }))
    .filter((c) => LANE_RE.test(c.text));

  const preferred = candidates.filter((c) => !OTHER_LANE_RE.test(c.text));
  const chosen = preferred.length ? preferred : candidates;

  const results = [];
  for (const { name, opt, text } of chosen) {
    let target;
    if (isBooleanOption(opt)) {
      target = true;
    } else {
      target = pickEnumValue(opt);
    }
    if (target === undefined) {
      results.push({ name, text, applied: false, reason: 'could not determine an "on" value', schema: opt });
