      if (opt.type === 'color') score -= 20;
      return { name, opt, text, score };
    })
    .filter((c) => /landmark/.test(c.text) && mixWords.test(c.text) && c.opt.type !== 'color')
    .sort((a, b) => b.score - a.score);

  if (!candidates.length) {
    console.warn(
      'No landmark colour-mix setting found in the basemap schema. Available settings:',
      Object.keys(schema)
    );
    return;
  }

  const strongestValue = (opt) => {
    const values = Array.isArray(opt.values) ? opt.values : null;
    if (values && values.length) {
      const numeric = values.every((v) => typeof v === 'number' || (typeof v === 'string' && v.trim() !== '' && !isNaN(Number(v))));
      if (numeric) {
        return values.reduce((best, v) => (Number(v) > Number(best) ? v : best), values[0]);
      }
      const rank = (v) => {
        const s = String(v).toLowerCase();
        if (/\b(full|fully|max|maximum|strongest|complete|solid|100%?)\b/.test(s)) return 4;
        if (/\b(strong|high|intense|heavy)\b/.test(s)) return 3;
        if (/\b(medium|mid|moderate|normal|default)\b/.test(s)) return 1;
        if (/\b(none|off|no|zero|0|low|weak|min|minimum|subtle|light|soft)\b/.test(s)) return -1;
        return 0;
      };
      let best = values[0];
      let bestIndex = 0;
      values.forEach((v, i) => {
        const r = rank(v);
        const br = rank(best);
        if (r > br || (r === br && i > bestIndex)) {
          best = v;
          bestIndex = i;
        }
      });
      return best;
    }
    if (opt.type === 'number' || typeof opt.default === 'number') {
      return typeof opt.maxValue === 'number' ? opt.maxValue : 1;
    }
    if (opt.type === 'boolean' || typeof opt.default === 'boolean') {
      return true;
    }
    return opt.maxValue !== undefined ? opt.maxValue : opt.default;
  };

  const { name, opt } = candidates[0];
  const value = strongestValue(opt);

  map.setConfigProperty(importId, name, value);

  const readBack = map.getConfigProperty(importId, name);
  const same =
    readBack === value ||
    String(readBack) === String(value) ||
    JSON.stringify(readBack) === JSON.stringify(value);

  if (same) {
    console.log(`Set "${importId}" config "${name}" to`, value, '(verified by read-back).');
  } else {
    console.warn(
      `Tried to set "${importId}" config "${name}" to`, value,
      'but read back', readBack,
      '. Other candidates:', candidates.slice(1).map((c) => c.name)
    );
  }
})();
